/* Port of the test_speed_chroma.c half of Netflix/vmaf c70debb10
 * ("libvmaf/test: port new adm/vif/speed tests"): est_params() on 13x9, 20x10
 * and 288x162 planes, compute_eigenvalues() on 5x5, 9x9 and 25x25 matrices
 * and get_speed_score() on a 48x27-block grid, against upstream's values and
 * tolerance (1e-4). Upstream's inputs and expected values are unchanged.
 * Upstream's test includes speed.c; the fork's tests do not include sources,
 * so it calls speed.c's test entries in speed_internal.h instead
 * (speed_internal_cpu_est_params(), speed_internal_cpu_compute_eigenvalues(),
 * speed_internal_cpu_speed_score()). est_params() runs with the scalar
 * covariance and matrix kernels, as in upstream's test. The data lives at file
 * scope (function size limit), one helper runs the three est_params() cases,
 * and est_params()'s status is checked. */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>

#include "test.h"
#include "feature/speed_internal.h"

/* NOLINTBEGIN(modernize-use-nullptr): C translation unit. The fork builds C as
 * C23, where clang-tidy also proposes the `nullptr` keyword, but this is a C
 * translation unit whose sources spell the null pointer constant `NULL` and
 * MSVC's documented /std:clatest C23 feature set does not include `nullptr`
 * while the required Windows build compiles this TU with cl.exe. ADR-1138. */

#define EPS (1e-4)

static int almost_equal(float a, float b)
{
    float diff = a > b ? a - b : b - a;
    return diff < EPS;
}

static int compare_floats(const void *a, const void *b)
{
    float fa = *(const float *)a;
    float fb = *(const float *)b;
    return (fa > fb) - (fa < fb);
}

