#define EST_MAX_BLOCKS ((size_t)54 * 96)
static float est_entropies[EST_MAX_BLOCKS];
static float est_variances[EST_MAX_BLOCKS];

typedef struct EstParamsCase {
    const float *pic;
    const float *expected_entropy;
    const float *expected_variance;
    SpeedInternalEstGeometry geom;
} EstParamsCase;

/* One est_params() case: upstream's geometry, the plane at sigma_nn 0.1,
 * every block's entropy and variance within 1e-4 of upstream's values. */
static char *check_est_params(const EstParamsCase *c)
{
    const SpeedInternalScoreSide out = {
        .entropies = est_entropies,
        .variances = est_variances,
    };
    mu_assert("est_params case exceeds the result buffers", c->geom.num_blocks <= EST_MAX_BLOCKS);
    const int err = speed_internal_cpu_est_params(&c->geom, c->pic, 0.1f, out);
    mu_assert("est_params failed (singular covariance matrix or no memory)", !err);
    for (size_t i = 0; i < c->geom.num_blocks; i++)
        mu_assert("entropy incorrect", almost_equal(est_entropies[i], c->expected_entropy[i]));
    for (size_t i = 0; i < c->geom.num_blocks; i++)
        mu_assert("variance incorrect", almost_equal(est_variances[i], c->expected_variance[i]));
    return NULL;
}

static char *test_est_params_13x9(void)
{
    const EstParamsCase c = {
        .pic = est_13x9_pic,
        .expected_entropy = est_13x9_entropy,
        .expected_variance = est_13x9_variance,
        .geom =
            {
                .operating_width = 13,
                .operating_height = 9,
                .block_size = 3,
                .truncated_width = 12,
                .truncated_height = 9,
                .num_blocks_horizontal = 4,
                .num_blocks_vertical = 3,
                .num_blocks = 12,
                .elements_in_block = 9,
                .submatrix_width = 10,
                .submatrix_height = 7,
            },
    };
    return check_est_params(&c);
}

static char *test_est_params_20x10(void)
{
    const EstParamsCase c = {
        .pic = est_20x10_pic,
        .expected_entropy = est_20x10_entropy,
        .expected_variance = est_20x10_variance,
        .geom =
            {
                .operating_width = 20,
                .operating_height = 10,
                .block_size = 3,
                .truncated_width = 18,
                .truncated_height = 9,
                .num_blocks_horizontal = 6,
                .num_blocks_vertical = 3,
                .num_blocks = 18,
                .elements_in_block = 9,
                .submatrix_width = 16,
                .submatrix_height = 7,
            },
    };
    return check_est_params(&c);
}

static char *test_est_params_288x162(void)
{
    const EstParamsCase c = {
        .pic = est_288x162_pic,
        .expected_entropy = est_288x162_entropy,
        .expected_variance = est_288x162_variance,
        .geom =
            {
                .operating_width = 288,
                .operating_height = 162,
                .block_size = 3,
                .truncated_width = 288,
                .truncated_height = 162,
                .num_blocks_horizontal = 96,
                .num_blocks_vertical = 54,
                .num_blocks = 5184,
                .elements_in_block = 9,
                .submatrix_width = 286,
                .submatrix_height = 160,
            },
    };
    return check_est_params(&c);
}

/* compute_eigenvalues() of a size x size matrix, sorted, against upstream's
 * sorted eigenvalues. The matrix is copied: the routine takes a non-const
 * pointer. */
static char *check_eigenvalues(const float *data, const float *expected, int size)
{
    float matrix[25 * 25];
    float tmp_buffer[25 * 25 * 5];
    float eigenvalues[25];
    mu_assert("eigenvalue case larger than the test buffers", size > 0 && size <= 25);
    memcpy(matrix, data, (size_t)size * (size_t)size * sizeof(float));
    speed_internal_cpu_compute_eigenvalues(matrix, eigenvalues, size, tmp_buffer);
    qsort(eigenvalues, (size_t)size, sizeof(float), compare_floats);
    for (int i = 0; i < size; i++) {
        mu_assert("test_get_eigenvalues: eigenvalue is not close",
                  almost_equal(eigenvalues[i], expected[i]));
    }
    return NULL;
}

static char *test_get_eigenvalues_5x5(void)
{
    return check_eigenvalues(eig_5_data, eig_5_expected, 5);
}

static char *test_get_eigenvalues_9x9(void)
{
    return check_eigenvalues(eig_9_data, eig_9_expected, 9);
}

static char *test_get_eigenvalues_25x25(void)
{
    return check_eigenvalues(eig_25_data, eig_25_expected, 25);
}

/* get_speed_score() over upstream's 1296 blocks of 9 elements (a 48x27
 * grid), sigma_nn and nn_floor 0, weighting mode 0. The score reads the
 * entropies and variances; the casts drop the file-scope const of upstream's
 * data, which it does not write. */
static char *test_get_speed_score(void)
{
    const SpeedInternalScoreSide ref = {
        .entropies = (float *)score_entropy_ref,
        .variances = (float *)score_variance_ref,
    };
    const SpeedInternalScoreSide dis = {
        .entropies = (float *)score_entropy_dis,
        .variances = (float *)score_variance_dis,
    };
    const float score = speed_internal_cpu_speed_score(1296, 9, ref, dis, 0.0f, 0.0f, 0);
    const float expected_score = 6.773138f;
    mu_assert("incorrect final score", almost_equal(score, expected_score));
    return NULL;
}

static char *run_tests_est_params(void)
{
    mu_run_test(test_est_params_13x9);
    mu_run_test(test_est_params_20x10);
    mu_run_test(test_est_params_288x162);
    return NULL;
}

char *run_tests(void)
{
    mu_run_test(run_tests_est_params);
    mu_run_test(test_get_eigenvalues_5x5);
    mu_run_test(test_get_eigenvalues_9x9);
    mu_run_test(test_get_eigenvalues_25x25);
    mu_run_test(test_get_speed_score);
    return NULL;
}

